{const o=bkOpen;bkOpen=async function(tab){const r=await o.apply(this,arguments);try{const bar=document.querySelector('.x50ov .x50tabs');if(bar&&!bar.querySelector('[data-t=line]')){const b=document.createElement('button');b.className='chip';b.dataset.t='line';b.innerHTML=`<span class="kanji">家系</span> ${TX('השושלת','The line')}`;bar.append(b);const body=document.querySelector('#bkBody');b.onclick=()=>{sfx('step');bar.querySelectorAll('[data-t]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));bkTab('line',body,()=>b.click())};if(tab==='line')b.click()}}catch(e){}return r}}

/* ================= 家の力 the strength of the house =================
   To rule for long it is not enough to be strong yourself: the house must be strong. A marriage alliance, grown heirs
   of good blood, generations of ancestors, a full treasury and loyal retainers hold power together. A weak house with
   an ageing lord and no grown heir invites お家騒動, the house troubles that tore the Uesugi apart in 1578 (御館の乱)
   when Kenshin died without naming one of his two adopted sons. Nothing here is forced: it is the long game of rule. */
const KD=()=>{if(!S)return{};S.kd=S.kd&&typeof S.kd==='object'?S.kd:{};const k=S.kd;if(typeof k.yr!=='number'){try{k.yr=tYear()}catch(e){k.yr=1460}}k.scar=+k.scar||0;k.chron=Array.isArray(k.chron)?k.chron:[];return k};
const kdSum=st=>Object.values(st||{}).reduce((a,b)=>a+(+b||0),0);
const kdAge=()=>{try{return Math.max(18,18+tYear()-KD().yr)}catch(e){return 18}};
function kdParts(){const c=S.clan||{},k=KD(),P=[];const add=(kj,n,v,mx)=>P.push({kj,n,v:Math.round(Math.max(-99,Math.min(mx,v))),mx});
 add('婚姻',TX('ברית נישואים','Marriage alliance'),c.spouse?18+(['army','econ','blood'].includes(c.spouse.trait)?4:0):0,22);
 const ad=(c.heirs||[]).filter(h=>h.age>=ADULT);add('世継',TX('יורשים בוגרים','Grown heirs'),Math.min(2,ad.length)*7+((c.heirs||[]).length>ad.length?2:0),16);
 const best=ad.reduce((m,h)=>Math.max(m,kdSum(h.stats)),0),mine=Math.max(1,kdSum(S.stats));add('血筋',TX('איכות הדם (גנטיקה)','Quality of blood'),best?Math.min(1,best/mine)*14:0,14);
 add('家系',TX('דורות של אבות','Generations of ancestors'),((c.gen||1)-1)*3,15);
 add('財',TX('עושר האוצר','Wealth of the treasury'),Math.log10(Math.max(1,S.gold||0))*3-6,12);
 const ret=c.ret||[];add('家臣',TX('נאמנות הנאמנים','Loyalty of retainers'),ret.length?ret.reduce((a,r)=>a+loy(r),0)/ret.length*.2:0,20);
 add('名誉',TX('כבוד','Honour'),(S.meiyo||0)/20,6);
 const age=kdAge();if(age>55)add('老',TX(`אדון מזדקן (גיל ${age})`,`An ageing lord (age ${age})`),-(age-55)*1.5,0);
 if(k.scar>0)add('乱',TX('צלקות של מחלוקת','Scars of strife'),-k.scar,0);return P}
function kdHouse(){try{return Math.max(0,Math.min(100,Math.round(kdParts().reduce((a,p)=>a+Math.max(p.v,p.mx<=0?p.v:0),0))))}catch(e){return 30}}
const kdTier=h=>h>=70?{kj:'盤石',n:TX('בית איתן כסלע','Firm as bedrock'),col:'#7fd08a'}:h>=50?{kj:'安泰',n:TX('בית יציב','A stable house'),col:'var(--gold)'}:h>=35?{kj:'動揺',n:TX('בית מתנדנד','A shaken house'),col:'#e0a050'}:{kj:'危殆',n:TX('בית בסכנה','A house in peril'),col:'#e05a4a'};
function kdCard(){const h=kdHouse(),t=kdTier(h),d=document.createElement('div');d.className='card';d.id='kdHouse';d.style.cssText='margin:8px 0;padding:10px 12px';
 d.innerHTML=`<div class="eyebrow"><span class="kanji">家の力</span> ${TX('כוח הבית','Strength of the house')}</div><div style="display:flex;align-items:center;gap:10px;margin:4px 0"><b style="font-size:26px;color:${t.col}">${h}</b><div style="flex:1;height:10px;border-radius:6px;background:rgba(255,255,255,.08);overflow:hidden"><i style="display:block;height:100%;width:${h}%;background:${t.col}"></i></div><span class="kanji" style="color:${t.col}">${t.kj}</span></div>
 <div class="muted" style="font-size:12px;margin-bottom:4px">${t.n} · ${TX(`ראש הבית בן ${kdAge()}`,`The head of the house is ${kdAge()}`)}</div>
 <div style="font-size:12px;line-height:1.55">${kdParts().map(p=>`<span class="kanji">${p.kj}</span> ${p.n}: <b style="color:${p.v<0?'#e05a4a':'inherit'}">${p.v>0?'+':''}${p.v}</b>${p.mx>0?`/${p.mx}`:''}`).join('<br>')}</div>
 <p class="muted" data-lt="1" style="font-size:12px;margin:6px 0 0">${TX('בית חזק (50+) מוסיף הכנסה ונאמנות ומעביר את השלטון בשקט. בית חלש (מתחת ל־35), במיוחד עם אדון זקן ובלי יורש בוגר, מזמין אוֹאִיֶה־סוֹדוֹ: מחלוקות ירושה שבהן קרובים ונאמנים קורעים את הבית, מחוזות נופלים והאוצר מתרוקן.','A strong house (50+) adds income and loyalty and passes power in peace. A weak house (under 35), above all with an old lord and no grown heir, invites o-ie sōdō: succession quarrels in which kin and retainers tear the house apart, provinces fall and the treasury empties.')}</p>`;return d}
/* a strong house pays: +3% income at 50, +6% at 70 */
{const o=prodRate;prodRate=function(){const r=o.apply(this,arguments);try{if(!S||!S.clan)return r;const h=kdHouse();return h>=70?Math.round(r*1.06):h>=50?Math.round(r*1.03):r}catch(e){return r}}}
