/* ================= 家系図 the family tree, and what each ancestor leaves behind =================
   In a kakeizu a single line is blood and a double line is adoption; ＝ is a marriage. Lords prized their trees:
   in 1566 Matsudaira Ieyasu won court leave to take the name Tokugawa, and his line was later traced to the Seiwa Genji,
   the Minamoto blood that the office of shōgun required. The four great lineages, 源平藤橘 (Minamoto, Taira, Fujiwara,
   Tachibana), each opened its own doors. Every ancestor in the tree also leaves a legacy (遺徳) by the deeds of his life. */
const KD_YU={gen:{kj:'源',n:TX('מינאמוטו (גֶנְגִ׳י)','Minamoto (Genji)'),d:TX('דם השוגונים: +6 לכוח הבית ויוקרה מול הנאמנים','The blood of shōguns: +6 house strength and prestige among retainers')},
 hei:{kj:'平',n:TX('טאירה (הֵייקֵה)','Taira (Heike)'),d:TX('דם לוחמי גֶנְפֵּיי: +3% חיים בכל קרב','The blood of the Genpei warriors: +3% health in every fight')},
 fuji:{kj:'藤',n:TX('פוג׳יווארה','Fujiwara'),d:TX('דם הקנצלרים של החצר: +1 חסד בחצר (פחות מס לבית הקיסר) ו־+3% הכנסה','The blood of the court regents: +1 court favour (a lighter levy) and +3% income')},
 tachi:{kj:'橘',n:TX('טאצ׳יבאנה','Tachibana'),d:TX('דם המשוררים והחכמים: הנאמנים נשארים נאמנים (+נאמנות יומית)','The blood of poets and sages: retainers stay true (daily loyalty)')}};
const kdYuCost=()=>40000+((S.clan&&S.clan.cities||[]).length)*2500;
function kdLegacy(){const L=KD_LIN().slice(-6),o={bu:0,chi:0,mei:0,list:[]};for(const x of L){const t=[];if((x.wins||0)>=60){o.bu++;t.push('武功')}if((x.prov||0)>=6){o.chi++;t.push('治績')}if((x.level||0)>=35){o.mei++;t.push('名声')}o.list.push({x,t})}
 o.bu=Math.min(5,o.bu);o.chi=Math.min(4,o.chi);o.mei=Math.min(3,o.mei);return o}
/* the legacies reach every part of rule: war, the treasury, the strength of the house */
{const o=foeScale;foeScale=function(ctx){o(ctx);try{if(!P||!S)return;const g=kdLegacy(),y=KD().yu;let m=1+.01*g.bu+(y==='hei'?.03:0);if(m>1){P.maxHp=Math.round(P.maxHp*m);P.hp=P.hpLag=P.maxHp}if(g.bu)P.ki=Math.min(100,(P.ki||0)+g.bu)}catch(e){}}}
{const o=prodRate;prodRate=function(){const r=o.apply(this,arguments);try{if(!S||!S.clan)return r;const g=kdLegacy(),m=1+.015*g.chi+(KD().yu==='fuji'?.03:0);return m>1?Math.round(r*m):r}catch(e){return r}}}
{const o=fyCourt;fyCourt=function(){const r=o.apply(this,arguments);try{return KD().yu==='fuji'?Math.min(6,r+1):r}catch(e){return r}}}
{const o=kdParts;kdParts=function(){const P=o.apply(this,arguments);try{const g=kdLegacy(),y=KD().yu;const v=g.mei*3+(y==='gen'?6:0);if(v)P.push({kj:'遺徳',n:TX('מורשת האבות והייחוס','Legacy of the ancestors and lineage'),v,mx:15})}catch(e){}return P}}
