function kdMonURL(sz){try{const id=myMon();if(!id)return'';const c=document.createElement('canvas');c.width=c.height=sz;const g=c.getContext('2d');monDraw(g,id,sz/2,sz/2,sz*.46,'#f0d590',null);return c.toDataURL()}catch(e){return''}}
const kdFig=(x,col,kn,flip)=>`<g transform="translate(${x},118)${flip?' scale(-1,1)':''}"><ellipse cx="0" cy="34" rx="30" ry="6" fill="rgba(0,0,0,.45)"/><path d="M-24 34 Q-26 6 -8 -2 L8 -2 Q26 6 24 34 Z" fill="${col}"/><path d="M-30 -2 L30 -2 L22 8 L-22 8Z" fill="${col}" opacity=".85"/><circle cx="0" cy="-12" r="9" fill="#e8c9a0"/><path d="M-6 -21 Q0 -30 6 -21 L3 -18 L-3 -18Z" fill="#1a1110"/>${kn?`<path d="M-16 20 L16 20" stroke="#d8b060" stroke-width="2"/>`:''}</g>`;
function kdScene(type,o){o=o||{};const mon=kdMonURL(120),R=(a,b)=>a+Math.random()*(b-a);let svg='',fx='',kj='',seal='',cls='';
 if(type==='katoku'){kj='家督';seal='継';svg=`<svg viewBox="0 0 320 178" preserveAspectRatio="xMidYMid meet"><circle cx="160" cy="76" r="60" fill="#8e1e14" opacity=".55"/>${mon?`<image href="${mon}" x="100" y="16" width="120" height="120" opacity=".25" style="transform-origin:160px 76px;animation:kdSpin 1.4s both"/>`:''}${kdFig(92,'#4a4038',0,0)}${kdFig(228,'#6b1f14',1,1)}<g style="animation:kdPass 2.2s .4s both ease-in-out"><path d="M88 108 L132 92" stroke="#e8e0d0" stroke-width="3" stroke-linecap="round"/><path d="M84 110 L92 106" stroke="#3a2a1a" stroke-width="5" stroke-linecap="round"/></g></svg>`;
  for(let i=0;i<14;i++)fx+=`<i class="em" style="left:${R(5,95)}%;animation-duration:${R(2.4,4.2)}s;animation-delay:${R(0,3)}s"></i>`}
 else if(type==='wed'){kj='祝言';seal='寿';svg=`<svg viewBox="0 0 320 178" preserveAspectRatio="xMidYMid meet"><rect x="0" y="150" width="320" height="28" fill="#5a1410"/><rect x="0" y="150" width="320" height="4" fill="#f0e8d8"/>${kdFig(110,'#1a1414',0,0)}${kdFig(210,'#f4efe6',0,1)}<g transform="translate(160,140)"><ellipse rx="16" ry="5" fill="#b0281a"/><ellipse cy="-6" rx="11" ry="4" fill="#c8321e"/><ellipse cy="-11" rx="7" ry="3" fill="#d8402a"/></g></svg>`;
  for(let i=0;i<22;i++)fx+=`<i class="pt" style="left:${R(0,100)}%;--dx:${R(-40,40)}px;background:${Math.random()<.5?'#f6c1cf':'#fbe4ea'};animation-duration:${R(3,6)}s;animation-delay:${R(-6,0)}s"></i>`}
 else if(type==='sodo'){kj='御家騒動';seal='乱';cls=' kdShake sodo';svg=`<svg viewBox="0 0 320 178" preserveAspectRatio="xMidYMid meet"><rect width="320" height="178" fill="#2a0c06" opacity=".6"/>${[...Array(9)].map((_,i)=>{const x=70+i*22;return`<path d="M${x-10} 160 Q${x-14} ${118-R(0,20)} ${x} ${82-R(0,26)} Q${x+14} ${118-R(0,20)} ${x+10} 160Z" fill="${i%2?'#ff7a1a':'#ffb030'}" opacity=".9" style="transform-origin:${x}px 160px;animation:kdFlick ${R(.45,.9).toFixed(2)}s ${R(0,.5).toFixed(2)}s infinite"/>`}).join('')}<g transform="translate(160,160)" fill="#0d0706"><rect x="-50" y="-30" width="100" height="30"/><path d="M-66 -30 L66 -30 L44 -48 L-44 -48Z"/><rect x="-30" y="-66" width="60" height="18"/><path d="M-46 -66 L46 -66 L28 -82 L-28 -82Z"/><rect x="-6" y="-16" width="12" height="16" fill="#ff8a2a" opacity=".7"/></g><path d="M0 178 L0 160 L320 160 L320 178Z" fill="#0d0706"/></svg>`;
  for(let i=0;i<24;i++)fx+=`<i class="em" style="left:${R(20,80)}%;animation-duration:${R(1.5,3)}s;animation-delay:${R(0,2)}s"></i>`}
 else if(type==='muhon'){kj='謀反';seal='叛';cls=' kdShake';svg=`<svg viewBox="0 0 320 178" preserveAspectRatio="xMidYMid meet"><path d="M0 178 L0 140 Q160 120 320 140 L320 178Z" fill="#160a07"/>${[0,1].map(sd=>{const bx=sd?236:84,col=sd?'#7a1a12':'#1d2a48';return[...Array(5)].map((_,i)=>`<g transform="translate(${bx+(i-2)*16},${150-Math.abs(i-2)*4})"><line x1="0" y1="0" x2="0" y2="-74" stroke="#2a1c10" stroke-width="2"/><rect x="0" y="-74" width="12" height="34" fill="${col}" style="transform-origin:0 -74px;animation:kdFlick ${R(.9,1.5).toFixed(2)}s ${R(0,.6).toFixed(2)}s infinite"/></g>`).join('')}).join('')}<g style="animation:kdStamp .5s .8s both"><path d="M140 150 L180 70 M180 150 L140 70" stroke="#d8d0c0" stroke-width="3"/></g></svg>`;
  for(let i=0;i<10;i++)fx+=`<i class="em" style="left:${R(35,65)}%;animation-duration:${R(1.6,3)}s;animation-delay:${R(0,2)}s"></i>`}
 else if(type==='claim'){kj=o.kj||'由緒';seal='証';svg=`<svg viewBox="0 0 320 178" preserveAspectRatio="xMidYMid meet"><g style="transform-origin:160px 100px;animation:kdUnroll 1.2s both cubic-bezier(.5,0,.2,1)"><rect x="30" y="84" width="260" height="76" fill="#efe2c4"/><rect x="22" y="80" width="10" height="84" rx="4" fill="#5a3418"/><rect x="288" y="80" width="10" height="84" rx="4" fill="#5a3418"/>${[...Array(9)].map((_,i)=>`<path d="M${262-i*26} 94 L${262-i*26} ${120+R(0,30)}" stroke="#2a1c10" stroke-width="3" stroke-linecap="round" opacity=".75"/>`).join('')}</g></svg>`}
 return`<div class="kdScene${cls}">${svg}${fx}<div class="kanji kj">${kj}</div>${seal?`<div class="kanji seal">${seal}</div>`:''}</div>`}
/* the society rows enter one by one, the numbers count up */
function kdAnim(root){try{root=root||$('#ovCard');let d=.9;root.querySelectorAll('.kdSoc>div[style*="border-top"]').forEach(r=>{r.classList.add('kdRow');r.style.animationDelay=(d+=.28)+'s'});
 root.querySelectorAll('b[data-n]').forEach(b=>{const n=+b.dataset.n,u=b.dataset.u||'',t0=performance.now()+d*600;const step=t=>{const k=Math.max(0,Math.min(1,(t-t0)/700));const v=Math.round(n*k);b.textContent=(v>0?'+':'')+v+u;if(k<1&&b.isConnected)requestAnimationFrame(step)};requestAnimationFrame(step)})}catch(e){}}
/* the ink ensō: the strength of the house as a brush circle */
function kdEnso(h,sz){const t=kdTier(h),r=sz*.38,C=2*Math.PI*r,L=C*Math.max(.02,h/100);return`<svg class="enso" width="${sz}" height="${sz}" viewBox="0 0 ${sz} ${sz}" style="flex:none"><defs><filter id="kdInk${sz}"><feTurbulence baseFrequency=".9" numOctaves="2" seed="4"/><feDisplacementMap in="SourceGraphic" scale="${sz/18}"/></filter></defs><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="${sz*.1}"/><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="${t.col}" stroke-width="${sz*.11}" stroke-linecap="round" stroke-dasharray="${L} ${C}" transform="rotate(-80 ${sz/2} ${sz/2})" filter="url(#kdInk${sz})"/><text x="50%" y="54%" text-anchor="middle" dominant-baseline="middle" font-size="${sz*.3}" font-weight="700" fill="${t.col}">${h}</text></svg>`}
/* scenes for every moment: hook the modals that the house already shows */
{const om=modal;modal=function(html,btns){try{if(typeof html==='string'){if(html.includes('家督相続')&&!html.includes('kdScene'))html=html.replace(/<div class="kanji" style="font-size:54px[^>]*>家督<\/div>/,'').replace(/^(<div class="eyebrow">[^<]*<\/div>)/,`$1${kdScene('katoku')}`);
  else if(html.includes('婚礼')&&!html.includes('kdScene'))html=html.replace(/<div class="kanji" style="font-size:48px[^>]*>祝言<\/div>/,'').replace(/^(<div class="eyebrow">[^<]*<\/div>)/,`$1${kdScene('wed')}`);
  else if(html.includes('由緒書')&&!html.includes('kdScene')){const m=html.match(/<div class="kanji" style="font-size:64px[^>]*>(.)<\/div>/);html=html.replace(/<div class="kanji" style="font-size:64px[^>]*>.<\/div>/,'').replace(/^(<div class="eyebrow">[^<]*<\/div>)/,`$1${kdScene('claim',{kj:m?m[1]+'氏':''})}`)}}}catch(e){}
 const r=om.call(this,html,btns);try{if(typeof html==='string'&&html.includes('kdScene')){kdAnim();kdShareBtn(html)}}catch(e){}return r}}
/* the house troubles get their own burning scene when you are there to see them */
{const o=kdSodo;kdSodo=function(notes){const r=o.apply(this,arguments);try{const t=notes[notes.length-1]||'';setTimeout(()=>{try{if(!S||autoOn()||$('#scr-hub').hidden||!$('#overlay').hidden)return;
  modal(`<div class="eyebrow">お家騒動 · ${TX('מחלוקת בבית','Trouble in the house')}</div>${kdScene('sodo')}<h2 style="text-align:center">${TX('הבית נקרע מבפנים','The house is torn from within')}</h2><p data-lt="1">${esc(t.replace(/^お家騒動\s*/,''))}</p><p class="muted" data-lt="1" style="font-size:12px">${TX('כדי שזה לא יקרה שוב: חזק את הבית. ברית נישואים, יורש בוגר, נאמנים מרוצים ואוצר מלא.','To keep it from happening again, strengthen the house: a marriage alliance, a grown heir, content retainers and a full treasury.')}</p>`,[{key:'ok',label:TX('לאחות את הבית','Mend the house'),cls:'gold'}])}catch(e){}},900)}catch(e){}return r}}
/* the society block: numbers that count, rows that arrive one by one */
{const o=kdSociety;kdSociety=function(){let h=o.apply(this,arguments);try{h=h.replace('<div style="margin-top:8px">','<div class="kdSoc" style="margin-top:8px">').replace(/<b style="color:(#[0-9a-f]+)">([+-]?)(\d+)([^<]*)<\/b>/g,(m,c,sg,n,u)=>`<b style="color:${c}" data-n="${sg==='-'?-n:+n}" data-u="${u.replace(/"/g,'&quot;')}">${sg}${n}${u}</b>`)}catch(e){}return h}}
/* the ensō replaces the flat bar in the strength card */
{const o=kdCard;kdCard=function(){const d=o.apply(this,arguments);try{const h=kdHouse(),bar=d.querySelector('div[style*="display:flex"]');if(bar){const t=kdTier(h);bar.innerHTML=`${kdEnso(h,84)}<div><div class="kanji" style="font-size:28px;color:${t.col}">${t.kj}</div><div style="font-size:13px">${t.n}</div><div class="muted" style="font-size:12px">${TX(`הדור ה־${(S.clan&&S.clan.gen)||1}`,`Generation ${(S.clan&&S.clan.gen)||1}`)}</div></div>`}}catch(e){}return d}}
/* the tree draws itself */
{const o=kdTreeSVG;kdTreeSVG=function(){let g=o.apply(this,arguments);try{let i=0;g=g.replace('<svg ','<svg class="kdTree" ').replace(/<line x1="([\d.-]+)" y1="([\d.-]+)" x2="([\d.-]+)" y2="([\d.-]+)"/g,(m,a,b,c,d)=>{const l=Math.ceil(Math.hypot(c-a,d-b))+2;return`<line style="--l:${l};animation-delay:${(i++*.12).toFixed(2)}s" x1="${a}" y1="${b}" x2="${c}" y2="${d}"`});let j=0;g=g.replace(/<rect x="([\d.-]+)" y="([\d.-]+)" width="(184|76)"/g,(m)=>`<rect class="nd" style="animation-delay:${(j++*.18).toFixed(2)}s" ${m.slice(6)}`)}catch(e){}return g}}
/* the house on the hub: an ensō, the generation, the age of the lord, one tap to the family tree */
{const o=renderHub;renderHub=function(){const r=o.apply(this,arguments);try{let el=$('#kdHub');if(el)el.remove();if(!S||!S.clan||((S.level||1)<8&&!S.clan.spouse&&(S.clan.gen||1)<2))return r;const host=document.querySelector('#scr-hub .stack')||$('#scr-hub');if(!host)return r;
 const h=kdHouse(),t=kdTier(h),k=KD(),y=KD_YU[k.yu],age=kdAge(),ad=(S.clan.heirs||[]).filter(x=>x.age>=ADULT).length;el=document.createElement('button');el.type='button';el.id='kdHub';el.className='card';
 el.style.cssText='display:flex;gap:12px;align-items:center;width:100%;text-align:start;padding:10px 12px;margin:8px 0;border:1px solid rgba(224,176,80,.35);background:linear-gradient(90deg,rgba(120,30,20,.25),rgba(0,0,0,0));color:inherit;font:inherit;cursor:pointer';
 el.innerHTML=`${kdEnso(h,62)}<div style="flex:1;min-width:0"><div class="eyebrow"><span class="kanji">家の力</span> ${TX('כוח הבית','Strength of the house')} · <span class="kanji" style="color:${t.col}">${t.kj}</span></div><div style="font-size:14px;font-weight:700">${y?`<span class="kanji">${y.kj}氏</span> `:''}${esc(kdFam())} · ${TX(`הדור ה־${S.clan.gen||1}`,`Generation ${S.clan.gen||1}`)}</div><div class="muted" style="font-size:12px">${TX(`האדון בן ${age}`,`The lord is ${age}`)} · ${S.clan.spouse?'💍':TX('בלי ברית נישואים','no marriage')} · ${TX(`${ad} יורשים בוגרים`,`${ad} grown heirs`)}${age>=55?` · <b style="color:#e05a4a">${TX('הזמן להכין יורש','time to ready an heir')}</b>`:''}${(()=>{try{const L=kdGrudges().filter(z=>z.g>=40);return L.length?` · <b style="color:#e05a4a">⚠ ${TX(`${L.length} בני בית ממורמרים`,`${L.length} resentful kin`)}</b>`:''}catch(e){return''}})()}</div></div><span class="kanji" style="font-size:22px;opacity:.7">家系</span>`;
 el.onclick=()=>{sfx('step');bkOpen('line')};const first=host.querySelector('#rkCard')||host.children[1]||null;host.insertBefore(el,first)}catch(e){}return r}}

/* a moment of the house is worth telling: one tap to share it with friends */
function kdShareBtn(html){try{if(typeof x50Share!=='function')return;const card=$('#ovCard');if(!card||card.querySelector('.kdShare'))return;const h2=(card.querySelector('h2')||{}).textContent||'';
 const kind=html.includes('婚礼')?TX('ברית נישואים','A marriage alliance'):html.includes('由緒書')?TX('ייחוס עתיק','An ancient lineage'):html.includes('お家騒動')?TX('מחלוקת בבית','Trouble in the house'):TX(`הדור ה־${(S.clan&&S.clan.gen)||1} של השושלת`,`Generation ${(S.clan&&S.clan.gen)||1} of the line`);
 const b=document.createElement('button');b.type='button';b.className='btn ghost wide kdShare';b.style.marginTop='6px';b.textContent=TX('📣 לשתף את הרגע','📣 Share this moment');
 b.onclick=e=>{e.stopPropagation();x50Share(TX(`בושידו ⚔️ ${kind}\n家 ${h2} · ${TX('כוח הבית','house')} ${kdHouse()}\nאפשר לבנות שושלת סמוראים משלך, דור אחרי דור:`,`Bushido ⚔️ ${kind}\n家 ${h2} · house strength ${kdHouse()}\nBuild your own samurai dynasty, generation after generation:`))};card.append(b)}catch(e){}}
